-- is-a: Der Untertyp erbt den Schlüssel, PK = FK
CREATE TABLE Fahrrad (
  FahrzeugID INT PRIMARY KEY REFERENCES Fahrzeug(FahrzeugID) ON DELETE CASCADE,
  AnzahlGaenge INT NOT NULL CHECK (AnzahlGaenge > 0)
);

-- is-part-of: Das Teil hängt vom Ganzen ab, zusammengesetzter PK
CREATE TABLE Position (
  BestellNr INT NOT NULL,
  PosNr INT NOT NULL,
  Menge INT NOT NULL CHECK (Menge > 0),
  PRIMARY KEY (BestellNr, PosNr),
  FOREIGN KEY (BestellNr) REFERENCES Bestellung(BestellNr) ON DELETE CASCADE
);
